-- Learning programs generated by a model on the learner's request.

CREATE TABLE generated_programs (
    id             TEXT PRIMARY KEY,           -- gen-<uuid>
    user_id        TEXT NOT NULL REFERENCES users(id),
    topic          TEXT NOT NULL,
    lang           TEXT NOT NULL,
    level          TEXT NOT NULL,              -- beginner | intermediate | advanced
    status         TEXT NOT NULL CHECK (status IN ('generating', 'ready', 'failed')),
    error          TEXT,
    lessons_total  INTEGER NOT NULL DEFAULT 0,
    lessons_done   INTEGER NOT NULL DEFAULT 0,
    model          TEXT,                       -- provider/model that wrote it (no secrets)
    content        TEXT,                       -- JSON GeneratedProgram, once outlined
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);
CREATE INDEX generated_programs_user_idx ON generated_programs(user_id, created_at);
